  if(!q)continue;const T=sd[0],nm=new Set();for(const m of cl.matchAll(new RegExp('\\b(?:'+T+'|LINK\\s+)(\\d+)(?:\\s*(?:to|through|-|–)\\s*(?:'+T+'|LINK\\s+)?(\\d+))?','gi')))for(let i=+m[1];i<=+(m[2]||m[1]);i++)nm.add(i);
